import { isValidPolicyNumber } from '../../src/claims/validate';

it('accepts legacy policy numbers', () => {
  expect(isValidPolicyNumber('P-123456')).toBe(true);
});

it('accepts current policy numbers', () => {
  expect(isValidPolicyNumber('POL-2026-000123')).toBe(true);
});

// Policy-number validation
// build {{sim.sessionId}}
const CURRENT = /^POL-\d{4}-\d{6}$/;
const LEGACY = /^P-\d{6}$/;

export function isValidPolicyNumber(value: string): boolean {
  return CURRENT.test(value) || LEGACY.test(value);
}

